class Solution {
public:
    int countSegments(string s) {
        int count = 0;
        int n = (int)s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] != ' ' && (i == 0 || s[i - 1] == ' ')) {
                count++;
            }
        }
        return count;
    }
};
